from __future__ import annotations

from phoenix.toolbox.qop.scalar import Scalar


class Summand:
    """
    Summand class
    """

    def __init__(self, bases: tuple, comps: tuple, coeff=None):
        self._comps = comps
        self._bases = bases
        if coeff is None:
            coeff = Scalar.identity()
        elif not isinstance(coeff, Scalar):
            coeff = Scalar(coeff)
        self._coeff = coeff
    def __init__(self, bases: tuple, comps: tuple, modif=None):
        self._comps = comps
        self._bases = bases
        if modif is None:
            modif = Scalar.identity()
        elif not isinstance(modif, Scalar):
            modif = Scalar(modif)
        self._modif = modif

    @property
    def comps(self):
        """access read-only attribute components"""
        return self._comps

    @property
    def bases(self):
        """access read-only attribute bases"""
        return self._bases

    @property
    def coeff(self):
        """access read-only attribute coefficient/prefix"""
        return self._coeff

    @property
    def prefix(self):
        """access read-only attribute prefix"""
        return self._coeff

    def copy(self):
        """copy a summand"""
        return Summand(self._bases, self._comps, self._coeff)
        """access read-only attribute coefficient/modifier"""
        return self._modif

    @property
    def modifier(self):
        """access read-only attribute modifier"""
        return self._modif

    def copy(self):
        """copy a summand"""
        return Summand(self._bases, self._comps, self._modif)
